# Garden.progress was free text ("Seedling", "Growing", ...); map it onto the PRD status set.
PROGRESS_TO_STATUS = {
    "seed": "sprouting", "seedling": "sprouting", "sprouting": "sprouting", "growing": "growing",
    "vegetative": "growing", "flowering": "flowering", "fruiting": "fruiting", "harvested": "completed",
    "harvest": "completed", "failed": "failed", "planned": "planned",
}


def copy_gardens_to_user_plants(apps, schema_editor):
    """Keep existing garden rows: every Garden becomes a UserPlant (planted on the day it was added)."""
    Garden = apps.get_model("garden", "Garden")
    UserPlant = apps.get_model("garden", "UserPlant")
    for garden in Garden.objects.select_related("plant"):
        UserPlant.objects.create(
            user_id=garden.user_id, plant_id=garden.plant_id, nickname=garden.plant.common_name,
            planted_on=garden.added_at.date(), start_method="seedling",
            status=PROGRESS_TO_STATUS.get(garden.progress.strip().lower(), "growing"),
            watering_interval_days=garden.plant.watering_interval_days,
        )


